const dialog=document.querySelector('#detail');const content=document.querySelector('#detail-content');let timer;function openDetail(html){content.innerHTML=html;dialog.showModal()}function closeDetail(){clearInterval(timer);dialog.close()}document.querySelector('.close').onclick=closeDetail;dialog.addEventListener('close',()=>clearInterval(timer));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDetail()}});
const titles=['기술을 배우고, 나의 언어를 발견하다.','AI와 함께 쓰는 기사, 질문에서 시작하다','숫자 너머의 이야기를 발견하는 방법','좋은 프롬프트는 좋은 관찰에서 나온다'];
const paragraphs=[['처음 AI 도구를 만났을 때는 빠르게 결과를 만드는 방법에 집중했습니다. 하지만 실험을 반복할수록 더 중요해진 것은 무엇을 표현하고 싶은지 스스로 묻는 일이었습니다.','한국경제 AI 교육에서 기사 초안을 작성하고, 이미지를 구상하고, 영상의 흐름을 설계하며 배움의 기록을 쌓아갑니다. 도구의 결과를 그대로 받아들이기보다 나의 관점으로 고치고 선택하는 과정을 담고자 합니다.','이 포트폴리오는 그 과정의 작은 전시 공간입니다. 완성된 결과물뿐 아니라 질문과 시행착오도 함께 기록할 예정입니다.'],['좋은 기사의 첫 문장보다 먼저 필요한 것은 좋은 질문입니다. 이번 실습에서는 하나의 주제를 여러 관점으로 나누고, 독자가 궁금해할 질문을 정리했습니다.','AI는 질문을 확장하고 초안의 구조를 비교하는 데 활용했습니다. 인용과 수치, 사실관계는 원문 자료와 대조해 확인한다는 원칙을 세웠습니다.'],['같은 숫자도 어떤 맥락에 놓이는지에 따라 다르게 읽힙니다. 데이터 스토리 실습에서는 변화의 크기뿐 아니라 비교 기준과 기간을 함께 살펴보는 데 집중했습니다.','표에서 발견한 패턴을 한 문장으로 설명하고, 그 문장을 뒷받침할 근거가 충분한지 다시 확인했습니다. 그래프는 장식이 아니라 이해를 돕는 도구로 사용합니다.'],['원하는 결과를 얻으려면 구체적으로 관찰하고 설명해야 합니다. 대상과 목적, 형식, 제약 조건을 나누어 요청문을 작성해 보았습니다.','한 번에 모든 조건을 바꾸지 않고 하나씩 수정하며 결과의 차이를 비교했습니다. 좋은 결과가 나온 이유를 기록하는 일이 다음 실험의 출발점이 되었습니다.']];
document.querySelectorAll('[data-article]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.article);openDetail(`<span class="eyebrow">LEARNING JOURNAL · 예시 기사</span><h2>${titles[i]}</h2><p>2026.09.10 · AI Atelier</p>${paragraphs[i].map(p=>`<p>${p}</p>`).join('')}`)});
document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.image);openDetail(`<span class="eyebrow">VISUAL STUDY 0${i+1} · AI 생성 예시</span><h2>${['The quiet balance','A closer look','Another atmosphere'][i]}</h2><img style="${i===2?'filter:saturate(.25) hue-rotate(160deg)':''}" src="assets/atelier.png" alt="종이와 금속 조형물"><p>${['형태의 균형과 따뜻한 자연광을 탐구한 생성 이미지입니다.','동일한 작품을 확대해 종이, 금속, 석재의 질감을 살펴본 구도 연구입니다.','동일한 작품에 색상 변화를 적용해 분위기를 비교한 이미지 연구입니다.'][i]}</p>`)});
document.querySelector('[data-demo]')?.addEventListener('click',()=>{openDetail('<span class="eyebrow">15초 스토리보드 미리보기</span><h2>일상을 다시 바라보다</h2><div class="demo-stage"><span id="scene-number">SCENE 01 / 03</span><h3 id="scene-title">Observe.</h3><p id="scene-copy">익숙한 형태를 천천히 관찰합니다.</p></div><div class="demo-progress"><div id="progress"></div></div><p><small>영상 파일 대신 장면의 순서를 보여주는 기획 데모입니다.</small></p>');let sec=0;const scenes=[['Observe.','익숙한 형태를 천천히 관찰합니다.'],['Explore.','빛과 질감 속에서 새로운 연결을 찾습니다.'],['Discover.','나만의 관점으로 이야기를 완성합니다.']];timer=setInterval(()=>{sec++;let i=Math.min(2,Math.floor(sec/5));document.querySelector('#scene-number').textContent=`SCENE 0${i+1} / 03`;document.querySelector('#scene-title').textContent=scenes[i][0];document.querySelector('#scene-copy').textContent=scenes[i][1];document.querySelector('#progress').style.width=`${sec/15*100}%`;if(sec>=15){clearInterval(timer);document.querySelector('#scene-number').textContent='미리보기 완료'}},1000)});
